using System;
using System.Threading;
using System.Threading.Tasks;
using Faolan.Core.Database.Repositories;
using Faolan.Core.Enums;
using Faolan.Core.Network;
using Faolan.Core.Network.Codecs.Team;
using Faolan.Core.Network.Logging;
using Faolan.Core.Network.Packets.Conan;
using Faolan.Core.Network.Protocol;
using Faolan.Core.Network.Server.CsPlayerAgent;
using Faolan.Core.Network.Server.GameServer;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace Faolan.CSPlayerAgent
{
	public partial class CsPlayerAgentListener : RpcServer<ConanMessageFramer>, ICsPlayerAgentProvider
	{
		// Composed collaborator: owns the guild RPC handlers, wire builders, and pending-invite / reply-endpoint
		// state. The cross-connection lookup (ClientForCharacter, on the Server base) is injected as a delegate seam.
		private readonly GuildService _guild;

		// World-listener seam: lets the guild flow check who is online (member records) and push the in-world
		// guild tag (0x2550C99A) onto a character's live GameServer connection on join/leave.
		private readonly IGameServerDispatcher _gameServerDispatcher;

		// Composed collaborator: owns the team roster and its dispatches - see TeamService.
		private readonly TeamService _teams;

		// Our own registration slot, so the world listener can route LeaveTeam/KickFromTeam here.
		private readonly ICsPlayerAgentDispatcher _csPlayerAgentDispatcher;

		// `port` is the hosting realm's CsPlayerAgentPort (from its Realm row - the single source of truth for the
		// realm-local service ports, #324), passed in at registration rather than read from global config.
		public CsPlayerAgentListener(ushort port, ILogger<CsPlayerAgentListener> logger, IConfiguration configuration, IDatabaseRepository database, IGameServerDispatcher gameServerDispatcher,
			ICsPlayerAgentDispatcher csPlayerAgentDispatcher) : base(port, logger, configuration, database, new ConanPacketTracer(logger, "CsPlayerAgent", typeof(CSPlayerInterfaceOpcodes)))
		{
			_gameServerDispatcher = gameServerDispatcher;
			_csPlayerAgentDispatcher = csPlayerAgentDispatcher;
			_guild = new GuildService(database, logger, gameServerDispatcher, ClientForCharacter);
			_teams = new TeamService(logger, gameServerDispatcher, ClientForCharacter);
		}

		public override Task StartAsync(CancellationToken cancellationToken)
		{
			// Registered here rather than injected, so the world listener can reach the team roster it does not own.
			_csPlayerAgentDispatcher.Register(this);
			return base.StartAsync(cancellationToken);
		}

		public override Task StopAsync(CancellationToken cancellationToken)
		{
			_csPlayerAgentDispatcher.Unregister(this);
			return base.StopAsync(cancellationToken);
		}

		// --- ICsPlayerAgentProvider: the team ops that arrive on the player's WORLD connection ------------------------
		public Task<bool> LeaveTeam(uint characterId)
		{
			return _teams.Leave(characterId);
		}

		public Task<bool> KickFromTeam(uint leaderId, uint targetId)
		{
			return _teams.Kick(leaderId, targetId);
		}

		protected override async Task ReceivedPacket(INetworkClient client, Rpc packet)
		{
			var opcode = (CSPlayerAgentOpcodes)packet.Opcode;
			LogPacketReceived(packet);

			// One reader over the body for the whole dispatch: BodyReader() hands out a fresh cursor per call, so the
			// handlers must share this instance rather than each re-reading from position 0. Cases that read inline use
			// it directly; those that hand off to a GuildService handler pass it in (the handler no longer re-reads).
			var body = packet.BodyReader();

			switch (opcode)
			{
				case CSPlayerAgentOpcodes.Authenticate:
				{
					var characterId = body.ReadUInt32();
					var accountId = body.ReadUInt32();
					var authReply = body.ReadUInt32();

					client.Session.Account = (await Database.GetAccount(accountId))!;
					if (client.Session.Account == null)
						throw new Exception($"Account not found: {accountId:X}");

					client.Session.Account.ClientInstance = characterId;

					// No `!` here on purpose: GetCharacterForAccount returns null for a character this account does not own,
					// and forgiving that makes the check below look like dead code someone will helpfully delete.
					client.Session.Character = await Database.GetCharacterForAccount(accountId, characterId)
						?? throw new Exception($"Character not found for account {accountId:X} and client instance {characterId:X}");

					await client.SendAsync(new Rpc(GuildService.ReplySender(packet.Receiver), packet.Sender, CSPlayerInterfaceOpcodes.DispatchAuthenticateAck, b => b.WriteUInt32(authReply)));

					// Guilded character: retail pushes the 0x203F full guild update right after the
					// Authenticate ack (claim_login_reward dump), before the 0x20D0/0x20C5 pair.
					await _guild.SendGuildStateOnLogin(client, packet);

					await client.SendAsync(new Rpc(GuildService.ReplySender(packet.Receiver), packet.Sender, CSPlayerInterfaceOpcodes.DispatchGroupFinderUpdateFeaturedActivities, (byte[])[0x01],
						b => b.WriteArray(0x00, 0x00, 0x03, 0xF1)));

					//if(character.Name == null)
					{
						await client.SendAsync(new Rpc(GuildService.ReplySender(packet.Receiver), packet.Sender, CSPlayerInterfaceOpcodes.DispatchGroupFinderRemoved, (byte[])[0x01],
							b => b
								.WriteString("<remoteformat token=\"GroupFinderCharacterLeftPlayfield\" category=\"100\" key=\"nKY&amp;+hL^I7&#36;M@PO`z&#39;Y0\" knubot=\"0\"  ></remoteformat>")
								.WriteByte(0x01)));
					}

					break;
				}

				// 0x2003 TeamInvite([ID32 target]): the leader (or a solo player) invites someone into a team.
				case CSPlayerAgentOpcodes.TeamInvite:
				{
					var targetId = TeamMessageCodec.ParseInviteTarget(body);
					if (await Database.GetCharacter(targetId) is { } target)
						await _teams.Invite(client, client.Session.Character, target);
					else
						Logger.LogWarning("TeamInvite for unknown character {TargetId:X8}.", targetId);

					break;
				}

				// 0x2008 AcceptTeamInvite([ID32 inviter]): the invitee joins. The inviter is taken from OUR pending
				// invite rather than the body, so a forged body cannot pull someone into a team they never invited to.
				case CSPlayerAgentOpcodes.AcceptTeamInvite:
				{
					TeamMessageCodec.ParseCharacterId(body); // the inviter, echoed by the client
					await _teams.AcceptInvite(client.Session.Character.Id);
					break;
				}

				// 0x2009 DeclineTeamInvite: drop the pending invite. Nothing goes on the wire in the capture.
				case CSPlayerAgentOpcodes.DeclineTeamInvite:
				{
					_teams.Decline(client.Session.Character.Id);
					break;
				}

				case CSPlayerAgentOpcodes.StartVoteRetreat:
				{
					var unk0 = body.ReadUInt32(); // 0x00, 0x00, 0xC3, 0x50
					var nClientInst = body.ReadUInt32();

					break;
				}

				case CSPlayerAgentOpcodes.RaidInviteCharacterByName:
				{
					break;
				}

				case CSPlayerAgentOpcodes.GuildGovernmentForm:
				{

					break;
				}

				case CSPlayerAgentOpcodes.AddGuildRenown:
				{

					break;
				}

				case CSPlayerAgentOpcodes.RemoveGuildRenown:
				{

					break;
				}

				case CSPlayerAgentOpcodes.ClientRequestGuildInfo:
				{
					await _guild.HandleClientRequestGuildInfo(client, packet, body);

					break;
				}

				case CSPlayerAgentOpcodes.AcceptGuildInvitation:
				{
					await _guild.HandleAcceptGuildInvitation(client, packet, body);

					break;
				}

				case CSPlayerAgentOpcodes.DeclineGuildInvitation:
				{
					var characterId = client.Session.Character?.Id ?? 0;
					var declinedGuild = _guild.DeclineGuildInvitation(characterId);
					if (declinedGuild != null)
						Logger.LogInformation("Guild invite to \"{Guild}\" declined by {CharacterId:X8}.", declinedGuild, characterId);

					break;
				}

				case CSPlayerAgentOpcodes.CreateGuild:
				{
					await _guild.HandleCreateGuild(client, packet, body);

					break;
				}

				case CSPlayerAgentOpcodes.GuildInviteByName:
				{
					await _guild.HandleGuildInviteByName(client, packet, body);

					break;
				}

				case CSPlayerAgentOpcodes.GuildInvite:
				{
					await _guild.HandleGuildInvite(client, packet, body);

					break;
				}

				case CSPlayerAgentOpcodes.GuildLeave:
				{
					await _guild.HandleGuildLeave(client);

					break;
				}

				case CSPlayerAgentOpcodes.GuildMessageOfTheDay:
				{
					await _guild.HandleGuildMessageOfTheDay(client, packet, body);

					break;
				}

				case CSPlayerAgentOpcodes.MassivePvpInfoRequest:
				{
					// The client polls the Massive-PvP guild leaderboard with 0x2077; retail answers each with a 0x20A5
					// DispatchMassivePvpInfoRequestReturn (verified in the login dump: 0x2077 -> 0x20A5).
					await SendMassivePvpInfo(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.GuildRequestMemberList:
				{
					// Retail answers the member-list request with a fresh 0x203F full update plus the 0x20A5 leaderboard.
					await _guild.SendGuildStateOnLogin(client, packet);
					await SendMassivePvpInfo(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.RequestRenownHistory:
				{
					// The renown-over-time graph in the guild window (retail answers with 0x2039). We track no history,
					// so we return a zeroed block (flat graph).
					await SendGuildRenownHistory(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.SearchForGuilds:
				{
					// The guild-finder browse window (0x2043 -> 0x205C). Return the realm's guilds.
					await SendGuildSearchResult(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.CharacterSearch:
				{
					// Character/"who" search (0x200A -> 0x2010). Empty result (no search index yet).
					await SendCharacterSearchResult(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.SearchForTeam:
				{
					// LFG team search (0x200B -> 0x200F). Empty result.
					await SendTeamSearchResult(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.PvPMatchMakingRequestInfo:
				{
					// PvP matchmaking info (0x2054 -> 0x2092). Empty / not-queued result.
					await SendPvpMatchMakingInfo(client, packet);

					break;
				}

				case CSPlayerAgentOpcodes.PvPMatchMakingIsInMatchMaking:
				{
					// "Am I queued for PvP matchmaking?" (0x2055). Retail sends no response; consume it so it isn't
					// logged as unhandled.
					break;
				}

				case CSPlayerAgentOpcodes.EchoGroupFinderRemoved:
				{
					// The client echoes a GroupFinder remoteformat back to us (e.g.
					// token="GroupFinderCharacterLeftPlayfield") - a notification the server consumes; no response
					// needed (retail pushes its own 0x20C5 downloads separately). Consume it so it isn't logged
					// as an unhandled packet.
					break;
				}

				case CSPlayerAgentOpcodes.EchoGroupFinderUpdateFeaturedActivities:
				{
					var unk0 = body.ReadUInt32();
					// { 0x00, 0x00, 0x03, 0xF1 } // Same data that we send in Authenticate

					break;
				}

				case CSPlayerAgentOpcodes.RemovePvpPoints:
				{
					var data = body.ReadRemainingArray();

					// Contains guild names or something like that
					// { 0x00, 0x00, 0xBD, 0x30, 0x00, 0x00, 0xDE, 0xB7, 0x00, 0x06, 0x1B, 0x28, 0x00, 0x08, 0x44, 0x61, 0x77, 0x6E, 0x73, 0x6F, 0x6E, 0x67, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0D, 0x35, 0x7E, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x26, 0xE0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0D, 0x0E, 0x9E, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, 0x18, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0xDE, 0xB7, 0x00, 0x06, 0x1B, 0x31, 0x00, 0x0F, 0x44, 0x65, 0x6D, 0x6F, 0x6E, 0x69, 0x63, 0x20, 0x4B, 0x6E, 0x69, 0x67, 0x68, 0x74, 0x73, 0x00, 0x00, 0x00, 0x00, 0x00, 0xBB, 0xA7, 0xCD, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xAF, 0x62, 0x00, 0x00, 0x00, 0x00, 0x00, 0xB6, 0xEB, 0x5C, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0x0D, 0x0F, 0x00, 0x00, 0x03, 0x65, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0xDE, 0xB7, 0x00, 0x06, 0x1D, 0x22, 0x00, 0x07, 0x44, 0x65, 0x73, 0x74, 0x69, 0x6E, 0x79, 0x00, 0x00, 0x00, 0x00, 0x00, 0x43, 0x4A, 0x12, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0C, 0xFA, 0x00, 0x00, 0x00, 0x00, 0x00, 0x42, 0x85, 0xD9, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xB7, 0x3F, 0x00, 0x00, 0x02, 0x71, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0xDE, 0xB7, 0x00, 0x06, 0x1D, 0xAD, 0x00, 0x14, 0x7B, 0x43, 0x69, 0x72, 0x63, 0x6C, 0x65, 0x20, 0x6F, 0x66, 0x20, 0x45, 0x74, 0x65, 0x72, 0x6E, 0x69, 0x74, 0x79, 0x7D, 0x00, 0x00, 0x00, 0x00, 0x00, 0x24, 0xBE, 0xD9, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x4B, 0x37, 0x00, 0x00, 0x00, 0x00, 0x00, 0x24, 0x73, 0xA2, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0x3C, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0xDE, 0xB7, 0x00, 0x06, 0x1E, 0x13, 0x00, 0x0C, 0x49, 0x2D, 0x53, 0x70, 0x61, 0x72, 0x74, 0x61, 0x6E, 0x73, 0x2D, 0x49, 0x00, 0x00, 0x00, 0x00, 0x00, 0x8A, 0x98, 0x56, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x01, 0xC2, 0x00, 0x00, 0x00, 0x00, 0x00, 0x84, 0x98, 0xCD, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0xFD, 0xC7, 0x00, 0x00, 0x01, 0x7B, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0xDE, 0xB7, 0x00, 0x06, 0x20, 0x6B, 0x00, 0x0A, 0x4D, 0x45, 0x4E, 0x45, 0x20, 0x54